practice.solution:
from sympy import symbols, sympify, diff, integrate, log, atan, asin, sin, cos, exp

x = symbols("x")
rank = {"L": 1, "I": 2, "A": 3, "T": 4, "E": 5}

def kind(f):
    if f.has(log):
        return "L"
    if f.has(atan) or f.has(asin):
        return "I"
    if f.has(sin) or f.has(cos):
        return "T"
    if f.has(exp):
        return "E"
    return "A"

n = int(input())
for i in range(1, n + 1):
    f = sympify(input())
    g = sympify(input())
    print(f"problem {i}: ({f}) * ({g}), letters {kind(f)} and {kind(g)}")
    if rank[kind(f)] <= rank[kind(g)]:
        u, dv = f, g
    else:
        u, dv = g, f
    print(f"  u = {u}, dv = {dv}")
    v = integrate(dv, x)
    print(f"  answer: {u*v - integrate(v * diff(u, x), x)} + C")
